mapper.update:
/* SQL ID : AsmtProfIndivDAO.asmtExlnBulkModify 설 명 : 우수과제 일괄 수정 */ MERGE INTO TB_LMS_ASMT_EVL EVL USING (
SELECT #{item.asmtEvlId} AS ASMT_EVL_ID , #{item.asmtId} AS ASMT_ID , #{item.userId} AS USER_ID , #{item.asmtSbmsnId} AS ASMT_SBMSN_ID , #{item.exlnAsmtyn} AS EXLN_ASMTYN , #{item.rgtrId} AS RGTR_ID , #{item.mdfrId} AS MDFR_ID FROM DUAL
) SRC ON ( EVL.ASMT_ID = SRC.ASMT_ID AND EVL.USER_ID = SRC.USER_ID ) WHEN MATCHED THEN UPDATE SET EVL.ASMT_SBMSN_ID = SRC.ASMT_SBMSN_ID , EVL.EXLN_ASMTYN = SRC.EXLN_ASMTYN , EVL.MDFR_ID = SRC.MDFR_ID , EVL.MOD_DTTM = FN_DTTM() WHEN NOT MATCHED THEN INSERT ( ASMT_EVL_ID , ASMT_ID , USER_ID , ASMT_SBMSN_ID , EVLYN , EXLN_ASMTYN , RGTR_ID , REG_DTTM ) VALUES ( SRC.ASMT_EVL_ID , SRC.ASMT_ID , SRC.USER_ID , SRC.ASMT_SBMSN_ID , 'N' , SRC.EXLN_ASMTYN , SRC.RGTR_ID , FN_DTTM() )

/*
	SQL ID : AsmtProfIndivDAO.asmtExlnModify
	설  명 : 우수과제 선정 수정
*/
UPDATE TB_LMS_ASMT_EVL
   SET EXLN_ASMTYN = #{exlnAsmtyn}
	 , MDFR_ID     = #{mdfrId}
	 , MOD_DTTM    = FN_DTTM()
 WHERE ASMT_ID     = #{asmtId}
   AND USER_ID     = #{userId}
